1	// Package calibrate 是本地器具校准与证书的本地台账。
2	//
3	// 台账只保存在本机指定文件中，不连接任何真实实验室。多次打开同一文件
4	// 可以继续查询与操作，不同文件之间的数据互不相干。
5	package calibrate
6	
7	import (
8		"encoding/json"
9		"errors"
10		"fmt"
11		"math"
12		"os"
13		"path/filepath"
14		"sort"
15		"strings"
16		"time"
17	)
18	
19	// 日期布局，所有入参日期都必须是实际存在的 YYYY-MM-DD。
20	const DateLayout = "2006-01-02"
21	
22	// Status 是器具的运行状态。
23	type Status string
24	
25	const (
26		// StatusPending 表示待校准，新登记器具的初始状态。
27		StatusPending Status = "待校准"
28		// StatusInUse 表示在用；在用本身不代表已经校准。
29		StatusInUse Status = "在用"
30		// StatusRetired 表示停用；停用不删除证书与使用记录。
31		StatusRetired Status = "停用"
32	)
33	
34	// ParseStatus 把命令行或文件中的状态文本解析为 Status。
35	func ParseStatus(s string) (Status, error) {
36		switch strings.TrimSpace(s) {
37		case string(StatusPending), "pending":
38			return StatusPending, nil
39		case string(StatusInUse), "in-use", "in_use":
40			return StatusInUse, nil
41		case string(StatusRetired), "retired":
42			return StatusRetired, nil
43		default:
44			return "", fmt.Errorf("无效状态 %q：只能是 在用、停用 或 待校准", s)
45		}
46	}
47	
48	// Instrument 是登记的器具信息。
49	type Instrument struct {
50		ID           string  `json:"id"`
51		Name         string  `json:"name"`
52		AllowedError float64 `json:"allowed_error"`
53		Status       Status  `json:"status"`
54		RegisteredAt string  `json:"registered_at"`
55	}
56	
57	// Certificate 是一张校准证书。
58	type Certificate struct {
59		Number       string  `json:"number"`
60		InstrumentID string  `json:"instrument_id"`
61		CalDate      string  `json:"cal_date"`
62		Expiry       string  `json:"expiry"`
63		Method       string  `json:"method"`
64		Error        float64 `json:"error"`
65		Summary      string  `json:"summary"`
66		CreatedAt    string  `json:"created_at"`
67	}
68	
69	// Pass 按证书自身数据判断是否合格：测得误差绝对值不超过允许误差（含限值）。
70	// 结论由数据计算，录入者不能自行选择。
71	func (c Certificate) Pass(allowedError float64) bool {
72		return math.Abs(c.Error) <= allowedError
73	}
74	
75	// UsageRecord 是一次使用申请的留痕，原因在申请发生时冻结。
76	type UsageRecord struct {
77		InstrumentID string   `json:"instrument_id"`
78		RequestedAt  string   `json:"requested_at"`
79		Allowed      bool     `json:"allowed"`
80		Reasons      []string `json:"reasons"`
81	}
82	
83	// ledgerData 是台账文件的持久化结构。
84	type ledgerData struct {
85		Version      int           `json:"version"`
86		Instruments  []Instrument  `json:"instruments"`
87		Certificates []Certificate `json:"certificates"`
88		Usage        []UsageRecord `json:"usage"`
89		Plans        []Plan        `json:"plans,omitempty"`
90	}
91	
92	// Ledger 是一份可操作的本地台账。
93	type Ledger struct {
94		path string
95		now  func() time.Time
96		data ledgerData
97	}
98	
99	// ValidationError 表示输入未通过业务校验，调用方不会改动任何已有记录。
100	type ValidationError struct{ Msg string }
101	
102	func (e *ValidationError) Error() string { return e.Msg }
103	
104	func validationError(format string, args ...any) error {
105		return &ValidationError{Msg: fmt.Sprintf(format, args...)}
106	}
107	
108	// IsValidation 报告 err 是否为业务校验错误。
109	func IsValidation(err error) bool {
110		var v *ValidationError
111		return errors.As(err, &v)
112	}
113	
114	// ConflictError 表示同号证书内容不一致等冲突，已有数据保持不变。
115	type ConflictError struct{ Msg string }
116	
117	func (e *ConflictError) Error() string { return e.Msg }
118	
119	// IsConflict 报告 err 是否为冲突错误。
120	func IsConflict(err error) bool {
121		var c *ConflictError
122		return errors.As(err, &c)
123	}
124	
125	// ErrNotFound 表示编号在台账中不存在。
126	var ErrNotFound = errors.New("记录不存在")
127	
128	func cleanText(s string) (string, error) {
129		t := strings.TrimSpace(s)
130		if t == "" {
131			return "", validationError("不能留空或只有空白")
132		}
133		return t, nil
134	}
135	
136	func parseFiniteDate(s, field string) (time.Time, string, error) {
137		t := strings.TrimSpace(s)
138		if t == "" {
139			return time.Time{}, "", validationError("%s不能留空", field)
140		}
141		parsed, err := time.Parse(DateLayout, t)
142		if err != nil {
143			return time.Time{}, "", validationError("%s必须是实际存在的日期（格式 YYYY-MM-DD）", field)
144		}
145		// time.Parse 对 YYYY-MM-DD 遇到超范围日期会直接报错；再用 Format
146		// 往返一次，拒绝 2024-2-3 之类格式不符的输入。
147		if parsed.Format(DateLayout) != t {
148			return time.Time{}, "", validationError("%s必须是实际存在的日期（格式 YYYY-MM-DD）", field)
149		}
150		return parsed, t, nil
151	}
152	
153	func finiteNumber(v float64, field string) error {
154		if math.IsNaN(v) || math.IsInf(v, 0) {
155			return validationError("%s必须是有限数", field)
156		}
157		return nil
158	}
159	
160	// Open 打开 path 所指的本机台账；文件不存在时建立一份新台账。
161	// 同一文件可以反复打开继续操作，不同 path 的数据互不混入。
162	func Open(path string) (*Ledger, error) {
163		return openAt(path, time.Now)
164	}
165	
166	func openAt(path string, now func() time.Time) (*Ledger, error) {
167		if strings.TrimSpace(path) == "" {
168			return nil, fmt.Errorf("台账文件路径不能为空")
169		}
170		l := &Ledger{
171			path: path,
172			now:  now,
173			data: ledgerData{Version: 1},
174		}
175		raw, err := os.ReadFile(path)
176		if err != nil {
177			if errors.Is(err, os.ErrNotExist) {
178				return l, nil
179			}
180			return nil, fmt.Errorf("读取台账 %s: %w", path, err)
181		}
182		if len(raw) > 0 {
183			if err := json.Unmarshal(raw, &l.data); err != nil {
184				return nil, fmt.Errorf("台账文件 %s 已损坏: %w", path, err)
185			}
186		}
187		if l.data.Version == 0 {
188			l.data.Version = 1
189		}
190		return l, nil
191	}
192	
193	// Path 返回台账文件位置。
194	func (l *Ledger) Path() string { return l.path }
195	
196	// save 把当前台账完整写回文件：先写临时文件再原子改名，
197	// 保证无效录入中断时不会留下半份记录。
198	func (l *Ledger) save() error {
199		if err := os.MkdirAll(filepath.Dir(l.path), 0o755); err != nil {
200			return fmt.Errorf("写入台账文件 %s 前创建目录失败: %w", l.path, err)
201		}
202		raw, err := json.MarshalIndent(l.data, "", "  ")
203		if err != nil {
204			return fmt.Errorf("序列化台账 %s: %w", l.path, err)
205		}
206		raw = append(raw, '\n')
207		tmp, err := os.CreateTemp(filepath.Dir(l.path), ".ledger-*.tmp")
208		if err != nil {
209			return fmt.Errorf("为台账 %s 创建临时文件: %w", l.path, err)
210		}
211		tmpName := tmp.Name()
212		defer os.Remove(tmpName)
213		if _, err := tmp.Write(raw); err != nil {
214			tmp.Close()
215			return fmt.Errorf("写入台账 %s 的临时文件: %w", l.path, err)
216		}
217		if err := tmp.Close(); err != nil {
218			return fmt.Errorf("关闭台账 %s 的临时文件: %w", l.path, err)
219		}
220		if err := os.Rename(tmpName, l.path); err != nil {
221			return fmt.Errorf("替换台账文件 %s: %w", l.path, err)
222		}
223		return nil
224	}
225	
226	func (l *Ledger) findInstrument(id string) *Instrument {
227		for i := range l.data.Instruments {
228			if l.data.Instruments[i].ID == id {
229				return &l.data.Instruments[i]
230			}
231		}
232		return nil
233	}
234	
235	func (l *Ledger) findCertificate(number string) *Certificate {
236		for i := range l.data.Certificates {
237			if l.data.Certificates[i].Number == number {
238				return &l.data.Certificates[i]
239			}
240		}
241		return nil
242	}
243	
244	// RegisterInput 是登记器具的输入。
245	type RegisterInput struct {
246		ID           string
247		Name         string
248		AllowedError float64
249	}
250	
251	// Register 登记一件新器具。编号、名称不得为空白，允许误差必须是不小于零的
252	// 有限数；编号重复或输入无效时明确拒绝，原记录不变。新器具处于待校准状态。
253	func (l *Ledger) Register(in RegisterInput) (*Instrument, error) {
254		id, err := cleanText(in.ID)
255		if err != nil {
256			return nil, fmt.Errorf("器具编号无效：%w", err)
257		}
258		name, err := cleanText(in.Name)
259		if err != nil {
260			return nil, fmt.Errorf("器具名称无效：%w", err)
261		}
262		if err := finiteNumber(in.AllowedError, "允许的绝对误差"); err != nil {
263			return nil, err
264		}
265		if in.AllowedError < 0 {
266			return nil, validationError("允许的绝对误差不能小于零")
267		}
268		if l.findInstrument(id) != nil {
269			return nil, validationError("器具编号 %s 已存在，编号必须唯一", id)
270		}
271		inst := Instrument{
272			ID:           id,
273			Name:         name,
274			AllowedError: in.AllowedError,
275			Status:       StatusPending,
276			RegisteredAt: l.now().Format(time.RFC3339),
277		}
278		l.data.Instruments = append(l.data.Instruments, inst)
279		if err := l.save(); err != nil {
280			return nil, err
281		}
282		return &inst, nil
283	}
284	
285	// SetStatus 切换器具状态。切换为在用不代表已校准；停用不删除证书与使用记录。
286	func (l *Ledger) SetStatus(id string, status Status) error {
287		switch status {
288		case StatusInUse, StatusRetired, StatusPending:
289		default:
290			return validationError("无效状态：只能是 在用、停用 或 待校准")
291		}
292		inst := l.findInstrument(id)
293		if inst == nil {
294			return fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
295		}
296		if inst.Status == status {
297			return nil
298		}
299		inst.Status = status
300		return l.save()
301	}
302	
303	// CertificateInput 是录入校准证书的输入。
304	type CertificateInput struct {
305		InstrumentID string
306		Number       string
307		CalDate      string
308		Expiry       string
309		Method       string
310		Error        float64
311		Summary      string
312	}
313	
314	// AddCertificate 录入一张校准证书并返回它；若同号证书且全部业务字段一致，
315	// 返回原证书且不增加历史（幂等）。同号内容不同报冲突且不改动已有数据。
316	//
317	// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
318	// 台账（含同一对象随后的查询）与录入前完全一致——失败的证书既不进入历史、
319	// 不占用证书编号或该器具当天的位置，也不会在此后其他成功操作写盘时被顺带写入；
320	// 恢复可写后重新提交同号同内容会作为新证书正常录入。
321	func (l *Ledger) AddCertificate(in CertificateInput) (*Certificate, bool, error) {
322		instID, err := cleanText(in.InstrumentID)
323		if err != nil {
324			return nil, false, fmt.Errorf("器具编号无效：%w", err)
325		}
326		number, err := cleanText(in.Number)
327		if err != nil {
328			return nil, false, fmt.Errorf("证书编号无效：%w", err)
329		}
330		method, err := cleanText(in.Method)
331		if err != nil {
332			return nil, false, fmt.Errorf("校准方法无效：%w", err)
333		}
334		summary, err := cleanText(in.Summary)
335		if err != nil {
336			return nil, false, fmt.Errorf("摘要无效：%w", err)
337		}
338		if err := finiteNumber(in.Error, "测得误差"); err != nil {
339			return nil, false, err
340		}
341	
342		inst := l.findInstrument(instID)
343		if inst == nil {
344			return nil, false, fmt.Errorf("器具编号 %s：%w", instID, ErrNotFound)
345		}
346	
347		_, calText, err := parseFiniteDate(in.CalDate, "校准日期")
348		if err != nil {
349			return nil, false, err
350		}
351		_, expText, err := parseFiniteDate(in.Expiry, "有效期截止日")
352		if err != nil {
353			return nil, false, err
354		}
355		// 与“本机今天”按日历日期比较，避免时分秒和时区造成边界误差。
356		todayText := l.now().Format(DateLayout)
357		if calText > todayText {
358			return nil, false, validationError("校准日期 %s 不能晚于本机今天 %s", calText, todayText)
359		}
360		if expText <= calText {
361			return nil, false, validationError("有效期截止日 %s 必须晚于校准日期 %s", expText, calText)
362		}
363	
364		if existing := l.findCertificate(number); existing != nil {
365			same := existing.InstrumentID == instID &&
366				existing.CalDate == calText &&
367				existing.Expiry == expText &&
368				existing.Method == method &&
369				existing.Summary == summary &&
370				existing.Error == in.Error
371			if !same {
372				return nil, false, &ConflictError{Msg: fmt.Sprintf(
373					"证书编号 %s 已存在且内容不同，拒绝覆盖已有数据", number)}
374			}
375			// 同号且全部业务字段一致：返回原证书，不增加历史记录。
376			return existing, true, nil
377		}
378	
379		// 同一器具同一天不接受两张不同编号的证书。
380		for i := range l.data.Certificates {
381			c := &l.data.Certificates[i]
382			if c.InstrumentID == instID && c.CalDate == calText {
383				return nil, false, validationError(
384					"器具 %s 在 %s 已有证书 %s，同一天不能再登记不同编号的证书",
385					instID, calText, c.Number)
386			}
387		}
388	
389		cert := Certificate{
390			Number:       number,
391			InstrumentID: instID,
392			CalDate:      calText,
393			Expiry:       expText,
394			Method:       method,
395			Error:        in.Error,
396			Summary:      summary,
397			CreatedAt:    l.now().Format(time.RFC3339),
398		}
399		// 在独立的新切片上暂存新证书：只有原子替换台账文件成功后才提交。
400		// 写盘失败时恢复原切片，保证同一台账对象随后看到的历史、最近证书、
401		// 证书编号占用与同日位置都与录入前一致，且不会被之后的写盘顺带写入。
402		original := l.data.Certificates
403		staged := make([]Certificate, 0, len(original)+1)
404		staged = append(staged, original...)
405		staged = append(staged, cert)
406		l.data.Certificates = staged
407		if err := l.save(); err != nil {
408			l.data.Certificates = original
409			return nil, false, err
410		}
411		return l.findCertificate(number), false, nil
412	}
413	
414	// certificatesOf 返回某器具的证书，按校准日期从新到旧排序；日期相同时
415	// （实际业务不会允许同日多证）以证书编号排序保证结果稳定。
416	func (l *Ledger) certificatesOf(id string) []Certificate {
417		var out []Certificate
418		for _, c := range l.data.Certificates {
419			if c.InstrumentID == id {
420				out = append(out, c)
421			}
422		}
423		sort.Slice(out, func(i, j int) bool {
424			if out[i].CalDate != out[j].CalDate {
425				return out[i].CalDate > out[j].CalDate
426			}
427			return out[i].Number < out[j].Number
428		})
429		return out
430	}
431	
432	// LatestCertificate 返回器具按校准日期确定的最近证书；没有证书时返回 nil。
433	// 最近证书与录入先后无关，补录较早证书只增加历史。
434	func (l *Ledger) LatestCertificate(id string) *Certificate {
435		cs := l.certificatesOf(id)
436		if len(cs) == 0 {
437			return nil
438		}
439		return &cs[0]
440	}
441	
442	// CertificateView 是证书及其在当前日期下的判定结果。
443	type CertificateView struct {
444		Certificate
445		Pass    bool `json:"pass"`
446		Expired bool `json:"expired"`
447	}
448	
449	func viewCertificate(c Certificate, allowed float64, today time.Time) CertificateView {
450		return CertificateView{
451			Certificate: c,
452			Pass:        c.Pass(allowed),
453			// 有效期截止日当天起即到期：按日历日期比较，今天 >= 截止日即为到期。
454			Expired: today.Format(DateLayout) >= c.Expiry,
455		}
456	}
457	
458	// UsageDecision 是一次使用申请的评估结果，原因在申请时冻结留痕。
459	type UsageDecision struct {
460		InstrumentID string
461		Allowed      bool
462		Reasons      []string
463		Latest       *CertificateView
464		evaluatedAt  time.Time
465	}
466	
467	// evaluateAt 按器具状态与“最近证书”判定 now 所在本机日历日期能否使用，
468	// 并列出全部适用原因。最近证书超差或到期时不会回退到更早的合格证书。
469	// 同一次核对的各部分必须共用同一个 now，避免跨午夜时判断不一致。
470	func (l *Ledger) evaluateAt(id string, now time.Time) (*Instrument, *UsageDecision) {
471		today := now
472		inst := l.findInstrument(id)
473		if inst == nil {
474			return nil, nil
475		}
476		d := &UsageDecision{InstrumentID: id, evaluatedAt: today}
477		if inst.Status != StatusInUse {
478			d.Reasons = append(d.Reasons, fmt.Sprintf("器具当前状态为%s，只有在用器具可以申请使用", inst.Status))
479		}
480		latest := l.LatestCertificate(id)
481		if latest == nil {
482			d.Reasons = append(d.Reasons, "没有校准证书")
483		} else {
484			v := viewCertificate(*latest, inst.AllowedError, today)
485			d.Latest = &v
486			if !v.Pass {
487				d.Reasons = append(d.Reasons, fmt.Sprintf(
488					"最近证书 %s 测得误差绝对值 %g 超过允许误差 %g，判定超差",
489					latest.Number, math.Abs(latest.Error), inst.AllowedError))
490			}
491			if v.Expired {
492				d.Reasons = append(d.Reasons, fmt.Sprintf("最近证书 %s 已于 %s 到期（截止日当天即到期）",
493					latest.Number, latest.Expiry))
494			}
495		}
496		d.Allowed = len(d.Reasons) == 0
497		return inst, d
498	}
499	
500	// CanUse 只按当前数据评估能否使用，不留存申请记录。
501	func (l *Ledger) CanUse(id string) (*UsageDecision, error) {
502		inst, d := l.evaluateAt(id, l.now())
503		if inst == nil {
504			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
505		}
506		return d, nil
507	}
508	
509	// cloneReasons 返回原因切片的独立副本，使对外返回的数据与台账内部存储
510	// 不共享底层数组：调用方替换、删减或补充返回结果中的原因，不会改写
511	// 已留痕的历史原因。nil 保持 nil，以维持空结果的既有表现。
512	func cloneReasons(in []string) []string {
513		if in == nil {
514			return nil
515		}
516		return append([]string(nil), in...)
517	}
518	
519	// RequestUse 针对已有器具提交使用申请：无论允许或拒绝都保存申请时间、结果
520	// 与当时全部原因。未知编号报错且不新增记录。
521	func (l *Ledger) RequestUse(id string) (*UsageDecision, error) {
522		if strings.TrimSpace(id) == "" {
523			return nil, fmt.Errorf("器具编号无效：%w", validationError("不能留空或只有空白"))
524		}
525		inst, d := l.evaluateAt(id, l.now())
526		if inst == nil {
527			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
528		}
529		// 留痕使用独立副本：返回给调用方的 d.Reasons 与其后的整理操作
530		// 不能成为改写台账内历史原因的途径。
531		rec := UsageRecord{
532			InstrumentID: id,
533			RequestedAt:  d.evaluatedAt.Format(time.RFC3339),
534			Allowed:      d.Allowed,
535			Reasons:      cloneReasons(d.Reasons),
536		}
537		if rec.Reasons == nil {
538			rec.Reasons = []string{}
539		}
540		l.data.Usage = append(l.data.Usage, rec)
541		if err := l.save(); err != nil {
542			return nil, err
543		}
544		return d, nil
545	}
546	
547	// InstrumentReview 是按器具核对的完整视图。
548	type InstrumentReview struct {
549		Instrument Instrument        `json:"instrument"`
550		CanUse     bool              `json:"can_use"`
551		Reasons    []string          `json:"reasons"`
552		Latest     *CertificateView  `json:"latest"`
553		History    []CertificateView `json:"history"`
554		Rejections []UsageRecord     `json:"rejections"`
555		Plans      []PlanView        `json:"plans"`
556	}
557	
558	// Review 按器具核对：登记信息、当前能否使用及原因、最近证书与到期日、
559	// 全部历史证书、被拒绝的使用记录以及该器具当前与已结束的校准计划。
560	// 整份核对只采用核对开始时的一次本机日期：即使查询结束前跨过午夜，
561	// 能否使用、最近证书、历史证书到期判断与未结束计划标记也不会各自变成新一天。
562	// 历史拒绝原因按申请当时的冻结内容展示，不随本次采用的日期重新计算。
563	func (l *Ledger) Review(id string) (*InstrumentReview, error) {
564		// 本次核对只在开始时取一次本机时间，整份结果共用，跨午夜不分裂判断；
565		// 下一次核对会重新取当时的本机日期，不沿用本次结果。
566		now := l.now()
567		inst, d := l.evaluateAt(id, now)
568		if inst == nil {
569			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
570		}
571		r := &InstrumentReview{
572			Instrument: *inst,
573			CanUse:     d.Allowed,
574			Reasons:    d.Reasons,
575			Latest:     d.Latest,
576		}
577		if r.Reasons == nil {
578			r.Reasons = []string{}
579		}
580		today := now
581		for _, c := range l.certificatesOf(id) {
582			r.History = append(r.History, viewCertificate(c, inst.AllowedError, today))
583		}
584		for _, u := range l.data.Usage {
585			if u.InstrumentID == id && !u.Allowed {
586				// 逐条深拷贝原因：对外核对视图中的历史拒绝记录只是展示副本，
587				// 调用方的整理不能回写台账，也不能影响其他入口已取得的结果。
588				u.Reasons = cloneReasons(u.Reasons)
589				r.Rejections = append(r.Rejections, u)
590			}
591		}
592		r.Plans = l.planViews(id, today)
593		return r, nil
594	}
595	
596	// Instruments 返回全部登记器具的副本，按编号排序。
597	func (l *Ledger) Instruments() []Instrument {
598		out := append([]Instrument(nil), l.data.Instruments...)
599		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
600		return out
601	}
602	
603	// UsageRecords 返回全部使用申请记录，按申请时间排序。
604	// 返回的是展示副本：整理其中原因不会改动台账内已冻结的留痕，
605	// 也不会被后续正常写盘带入文件。
606	func (l *Ledger) UsageRecords() []UsageRecord {
607		out := append([]UsageRecord(nil), l.data.Usage...)
608		for i := range out {
609			out[i].Reasons = cloneReasons(out[i].Reasons)
610		}
611		sort.SliceStable(out, func(i, j int) bool {
612			if out[i].RequestedAt != out[j].RequestedAt {
613				return out[i].RequestedAt < out[j].RequestedAt
614			}
615			return out[i].InstrumentID < out[j].InstrumentID
616		})
617		return out
618	}
619

