234	func cmdRegister(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
235		fs := newFlagSet("register", &opts)
236		id := fs.String("id", "", "器具唯一编号")
237		name := fs.String("name", "", "器具名称")
238		allowed := fs.String("allowed", "", "允许的绝对误差（不小于零的有限数）")
239		if err := fs.Parse(args); err != nil {
240			fmt.Fprintln(stderr, "register 参数错误：", err)
241			return 2
242		}
243		if *id == "" || *name == "" || *allowed == "" {
244			fmt.Fprintln(stderr, "register 必须提供 --id、--name、--allowed")
245			return 2
246		}
247		allowedErr, ok := parseFloat(stderr, *allowed, "允许的绝对误差")
248		if !ok {
249			return 2
250		}
251		inst, err := l.Register(calibrate.RegisterInput{
252			ID: *id, Name: *name, AllowedError: allowedErr,
253		})
254		if err != nil {
255			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
256				return failBusiness(opts, stdout, stderr, err,
257					map[string]any{"accepted": false, "error": err.Error()})
258			}
259			return failIO(stderr, err)
260		}
261		human := fmt.Sprintf("已登记器具 %s（%s），允许绝对误差 %g，状态：%s\n",
262			inst.ID, inst.Name, inst.AllowedError, inst.Status)
263		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "instrument": inst})
264	}
