148		}
149		if ok.Changes[0] != savedFirst {
150			t.Fatalf("第一条改期记录不能变化：原 %+v 现 %+v", savedFirst, ok.Changes[0])
151		}
152		second := ok.Changes[1]
153		wantSecond := PlanChange{
154			From:      "2026-10-20",
155			To:        "2026-11-08",
156			Reason:    "改造完成重新排期",
157			ChangedAt: "2026-10-21T00:00:00Z",
158		}
159		if second != wantSecond {
160			t.Fatalf("新增记录应为最后成功日期 10-20 到 11-08、采用本次操作时间：%+v", second)
161		}
162	
163		// 重新打开文件：磁盘上同样只有两条记录且无 11-05。
164		reopened, err = openAt(path, clock.now)
165		if err != nil {
166			t.Fatalf("reopen: %v", err)
167		}
168		rp = reopened.findPlan("P-1")
169		if rp == nil || rp.PlannedDate != "2026-11-08" || len(rp.Changes) != 2 {
