1	package calibrate
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// blockSaving 让台账文件无法被原子替换：把台账文件改成同名目录后，
12	// save() 的 Rename 会稳定失败（即使以 root 运行也无法用文件覆盖目录）。
13	// 已打开的台账对象仍可在内存中继续查询；restoreSaving 恢复可写，
14	// 全程不需要关闭并重新打开台账。
15	func blockSaving(t *testing.T, l *Ledger) {
16		t.Helper()
17		if err := os.Remove(l.path); err != nil {
18			t.Fatalf("移除台账文件以构造写盘失败: %v", err)
19		}
20		if err := os.Mkdir(l.path, 0o755); err != nil {
21			t.Fatalf("以同名目录挡住台账替换: %v", err)
22		}
23	}
24	
25	func restoreSaving(t *testing.T, l *Ledger) {
26		t.Helper()
27		// 挡路的是空目录（save 的临时文件已被 defer 清理），移除后下一次
28		// Rename 即可把临时文件改成台账文件。
29		if err := os.Remove(l.path); err != nil {
30			t.Fatalf("移除挡路目录以恢复可写: %v", err)
31		}
32	}
33	
34	// TestFailedCertificateSaveLeavesNoConclusion 覆盖核心修复：已通过业务校验的
35	// 新证书在写盘失败时明确报保存错误，台账状态与录入前完全一致。
36	func TestFailedCertificateSaveLeavesNoConclusion(t *testing.T) {
37		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
38		path := filepath.Join(t.TempDir(), "ledger.json")
39		l, err := openAt(path, clock.now)
40		if err != nil {
41			t.Fatalf("open: %v", err)
42		}
43		mustRegister(t, l, "M-1", "万用表", 0.5)
44		if err := l.SetStatus("M-1", StatusInUse); err != nil {
45			t.Fatalf("set in-use: %v", err)
46		}
47	
48		in := CertificateInput{
49			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-09-01",
50			Expiry: "2027-09-01", Method: "规范A", Error: 0.1, Summary: "摘要",
51		}
52	
53		blockSaving(t, l)
54	
55		cert, dup, err := l.AddCertificate(in)
56		if err == nil {
57			t.Fatal("台账文件无法替换时必须返回保存错误")
58		}
59		if cert != nil || dup {
60			t.Fatalf("保存失败不能返回已录入或重复证书：cert=%v dup=%v", cert, dup)
61		}
62		if IsValidation(err) || IsConflict(err) || errors.Is(err, ErrNotFound) {
63			t.Fatalf("写盘失败应是保存错误而非业务拒绝：%v", err)
64		}
65	
66		// 继续使用同一台账对象：历史、最近证书与使用资格都与录入前一致。
67		if n := len(l.data.Certificates); n != 0 {
68			t.Fatalf("失败证书进入了内存台账：%d 张", n)
69		}
70		if l.findCertificate("C-1") != nil {
71			t.Fatal("失败证书仍能按编号找到")
72		}
73		if n := len(l.certificatesOf("M-1")); n != 0 {
74			t.Fatalf("失败证书进入了器具历史：%d 张", n)
75		}
76		if latest := l.LatestCertificate("M-1"); latest != nil {
77			t.Fatalf("无证书器具在失败录入后出现最近证书：%+v", latest)
78		}
79		d, err := l.CanUse("M-1")
80		if err != nil {
81			t.Fatalf("can use: %v", err)
82		}
83		if d.Allowed || !containsReason(d.Reasons, "没有校准证书") {
84			t.Fatalf("失败的合格证书不得解除无证书限制：allowed=%v reasons=%v", d.Allowed, d.Reasons)
85		}
86		r, _ := l.Review("M-1")
87		if r.CanUse || r.Latest != nil || len(r.History) != 0 {
88			t.Fatalf("核对结果应与录入前一致：canUse=%v latest=%v history=%d",
89				r.CanUse, r.Latest, len(r.History))
90		}
91	
92		// 文件仍不可保存时，再次提交同号同内容应再次报保存失败，而不是以重复
93		// 证书为由跳过保存返回成功。
94		if _, dup, err := l.AddCertificate(in); err == nil || dup {
95			t.Fatalf("再次提交应仍报保存失败且不是重复证书：err=%v dup=%v", err, dup)
96		}
97	
98		// 失败的证书不占用当天位置：同日换个编号必须走到写盘（再次保存失败），
99		// 而不能被“同一器具同一天已有证书”的校验挡住。
100		sameDay := in
101		sameDay.Number = "C-2"
102		if _, _, err := l.AddCertificate(sameDay); err == nil || IsValidation(err) {
103			t.Fatalf("失败证书不得占用同日位置，同日新证书应再次保存失败而非业务拒绝：%v", err)
104		}
105		if l.findCertificate("C-2") != nil || len(l.data.Certificates) != 0 {
106			t.Fatal("同日重试的失败证书也不能留下记录")
107		}
108	
109		// 恢复文件可写后不必重开台账：先做一件与该证书无关、能够成功保存的正常
110		// 操作，失败的证书不能被顺带写入文件。
111		restoreSaving(t, l)
112		if err := l.SetStatus("M-1", StatusRetired); err != nil {
113			t.Fatalf("恢复后正常操作应能保存: %v", err)
114		}
115		reopened, err := openAt(path, clock.now)
116		if err != nil {
117			t.Fatalf("reopen: %v", err)
118		}
119		if len(reopened.data.Certificates) != 0 || reopened.findCertificate("C-1") != nil {
120			t.Fatalf("失败证书被随后成功的写盘顺带写入文件：%+v", reopened.data.Certificates)
121		}
122	
123		// 在同一台账对象上重新提交同号同内容：作为新证书正常录入并进入历史。
124		if err := l.SetStatus("M-1", StatusInUse); err != nil {
125			t.Fatalf("set in-use: %v", err)
126		}
127		cert, dup, err = l.AddCertificate(in)
128		if err != nil || dup || cert == nil {
129			t.Fatalf("恢复后重新提交应作为新证书录入：err=%v dup=%v cert=%v", err, dup, cert)
130		}
131		if cert.Number != "C-1" {
132			t.Fatalf("返回的新证书编号异常：%s", cert.Number)
133		}
134		if n := len(l.certificatesOf("M-1")); n != 1 {
135			t.Fatalf("新证书应进入历史，得到 %d 张", n)
136		}
137		// 真正保存成功后才参与最近证书与使用资格判断。
138		d, _ = l.CanUse("M-1")
139		if !d.Allowed || d.Latest == nil || d.Latest.Number != "C-1" {
140			t.Fatalf("保存成功后应解除无证书限制：allowed=%v latest=%v", d.Allowed, d.Latest)
141		}
142		reopened, _ = openAt(path, clock.now)
143		if reopened.findCertificate("C-1") == nil || len(reopened.data.Certificates) != 1 {
144			t.Fatal("保存成功的证书应已进入台账文件")
145		}
146	
147		// 真实保存成功后，该编号与同日位置才被占用：同日另一编号现在按现有规则拒绝。
148		if _, _, err := l.AddCertificate(sameDay); !IsValidation(err) ||
149			!strings.Contains(err.Error(), "同一天") {
150			t.Fatalf("成功录入后同日位置才应被占用，得到 %v", err)
151		}
152	}
153	
154	// TestFailedQualifiedCertificateCannotLiftRestriction 验证最近证书超差或到期
155	// 的器具，不会因一张保存失败的合格（且更近、未到期）证书而被解除限制。
156	func TestFailedQualifiedCertificateCannotLiftRestriction(t *testing.T) {
157		cases := []struct {
158			name   string
159			bad    CertificateInput
160			good   CertificateInput
161			reason string
162		}{
163			{
164				name:   "最近证书超差",
165				bad:    CertificateInput{InstrumentID: "M-1", Number: "C-BAD", CalDate: "2026-09-01", Expiry: "2027-09-01", Method: "m", Error: 5, Summary: "s"},
166				good:   CertificateInput{InstrumentID: "M-1", Number: "C-GOOD", CalDate: "2026-09-15", Expiry: "2027-09-15", Method: "m", Error: 0, Summary: "s"},
167				reason: "超差",
168			},
169			{
170				name:   "最近证书到期",
171				bad:    CertificateInput{InstrumentID: "M-1", Number: "C-OLD", CalDate: "2025-01-01", Expiry: "2025-12-31", Method: "m", Error: 0, Summary: "s"},
172				good:   CertificateInput{InstrumentID: "M-1", Number: "C-GOOD", CalDate: "2026-09-15", Expiry: "2027-09-15", Method: "m", Error: 0, Summary: "s"},
173				reason: "到期",
174			},
175		}
176		for _, tc := range cases {
177			t.Run(tc.name, func(t *testing.T) {
178				clock := &fakeClock{t: mustDate(t, "2026-10-02")}
179				path := filepath.Join(t.TempDir(), "ledger.json")
180				l, err := openAt(path, clock.now)
181				if err != nil {
182					t.Fatalf("open: %v", err)
183				}
184				mustRegister(t, l, "M-1", "万用表", 0.5)
185				mustAddCert(t, l, tc.bad)
186				_ = l.SetStatus("M-1", StatusInUse)
187	
188				before, _ := l.CanUse("M-1")
189				if before.Allowed || !containsReason(before.Reasons, tc.reason) {
190					t.Fatalf("前置条件失效：应因%s不能使用，得到 %v", tc.reason, before.Reasons)
191				}
192	
193				blockSaving(t, l)
194				if _, _, err := l.AddCertificate(tc.good); err == nil {
195					t.Fatal("写盘失败应返回保存错误")
196				}
197	
198				// 同一对象核对：限制不被解除，最近证书仍是旧的那张，历史不增加。
199				d, _ := l.CanUse("M-1")
200				if d.Allowed || !containsReason(d.Reasons, tc.reason) {
201					t.Fatalf("失败的合格证书不得解除%s限制：allowed=%v reasons=%v",
202						tc.reason, d.Allowed, d.Reasons)
203				}
204				r, _ := l.Review("M-1")
205				if r.CanUse || r.Latest == nil || r.Latest.Number != tc.bad.Number {
206					t.Fatalf("最近证书不应变化：canUse=%v latest=%v", r.CanUse, r.Latest)
207				}
208				if len(r.History) != 1 || r.History[0].Number != tc.bad.Number {
209					t.Fatalf("失败证书不得进入历史：%+v", r.History)
210				}
211			})
212		}
213	}
