462		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
463		l := newTestLedger(t, clock)
464		mustRegister(t, l, "M-1", "万用表", 0.5)
465		mustPlan(t, l, PlanInput{Number: "P-OLD", InstrumentID: "M-1", Date: "2026-10-10", Note: "旧"})
466		mustAddCert(t, l, CertificateInput{
467			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-10-02",
468			Expiry: "2027-10-02", Method: "m", Error: 0.1, Summary: "s",
469		})
470		if _, _, err := l.CompletePlan("P-OLD", "C-1"); err != nil {
471			t.Fatalf("complete old: %v", err)
472		}
473		// 新的未结束计划，含一次改期。
474		mustPlan(t, l, PlanInput{Number: "P-NEW", InstrumentID: "M-1", Date: "2026-11-01", Note: "新"})
475		if _, err := l.ReschedulePlan("P-NEW", "2026-11-05", "车间占用"); err != nil {
476			t.Fatalf("reschedule: %v", err)
477		}
478	
479		r, err := l.Review("M-1")
480		if err != nil {
481			t.Fatalf("review: %v", err)
482		}
483		if len(r.Plans) != 2 {
484			t.Fatalf("核对应同时展示当前及已结束计划，得到 %d", len(r.Plans))
485		}
486		var old, cur *PlanView
487		for i := range r.Plans {
488			switch r.Plans[i].Number {
489			case "P-OLD":
490				old = &r.Plans[i]
491			case "P-NEW":
492				cur = &r.Plans[i]
493			}
494		}
495		if old == nil || old.Status != PlanStatusDone || old.CertificateNumber != "C-1" {
496			t.Fatalf("已结束计划及关联证书展示异常：%+v", old)
497		}
498		if cur == nil || cur.PlannedDate != "2026-11-05" || cur.OriginalDate != "2026-11-01" {
499			t.Fatalf("当前计划日期展示异常：%+v", cur)
500		}
501		if len(cur.Changes) != 1 || cur.Changes[0].Reason != "车间占用" {
502			t.Fatalf("改期记录未展示：%+v", cur)
503		}
504		if cur.Marker != TodoFuture {
505			t.Fatalf("未来计划标记应为未到计划日，得到 %s", cur.Marker)
506		}
507	}
508	
509	func TestPlansPersistAndOldLedgerHasNoPlans(t *testing.T) {
510		dir := t.TempDir()
511		path := filepath.Join(dir, "ledger.json")
512		clock := func() time.Time { return mustDate(t, "2026-10-02") }
