33	func runArgs(t *testing.T, args ...string) result {
34		t.Helper()
35		var out, errBuf bytes.Buffer
36		code := run(args, &out, &errBuf)
37		return result{code: code, stdout: out.String(), stderr: errBuf.String()}
38	}
