57	func readUsageCount(t *testing.T, path string) int {
58		t.Helper()
59		raw, err := os.ReadFile(path)
60		if err != nil {
61			t.Fatalf("读取台账 %s: %v", path, err)
62		}
63		var data struct {
64			Usage []json.RawMessage `json:"usage"`
65		}
66		if err := json.Unmarshal(raw, &data); err != nil {
67			t.Fatalf("解析台账 %s: %v", path, err)
68		}
69		return len(data.Usage)
70	}
